query:
MATCH (e:Entity {id: $target_id}), (n:Label {id: $label_id})
             CREATE (e)-[:HAS_LABEL {
               assigned_by: $assigned_by, created_at: $created_at, properties: $properties
             }]->(n)

MATCH (e:Entity {id: $target_id}), (n:Community {id: $community_id})
             CREATE (e)-[:BELONGS_TO {
               strength: $strength, created_at: $created_at, properties: $properties
             }]->(n)

CREATE (o:GovernanceOperation {
               id: $id, operation_type: $operation_type, source_id: $source_id,
               target_id: $target_id, payload: $payload, actor: $actor,
               created_at: $created_at
             })

CREATE (o:GovernanceOperation {
           id: $id, operation_type: $operation_type, source_id: $source_id,
           target_id: $target_id, payload: $payload, created_at: $created_at
         })

CREATE (operation:GovernanceOperation {
                id: $id, operation_type: 'memory.evolves.revise',
                source_id: $source_id, target_id: $target_id,
                payload: $payload, created_at: $now
            })

MATCH (t:Thread {id: $thread_uuid}), (m:Memory {id: $memory_id})
         WHERE NOT EXISTS { MATCH (t)-[:COMPACTS_TO]->(m) }
         CREATE (t)-[:COMPACTS_TO {compaction_method: $method, created_at: $created_at, properties: $props}]->(m)

MATCH (c:Memory)-[:CRYSTALLIZED_FROM]->(s:Memory)
         WHERE NOT EXISTS { MATCH (c)-[:SYNTHESIZED_FROM]->(s) }
         RETURN count(*)
